import re, json
html=open("/tmp/embed.html","r",errors="replace").read()
# find ytcfg set
idxs=[]
for m in re.finditer(r"ytcfg\.set\(", html):
    idxs.append(m.start())
print("ytcfg.set count", len(idxs), "positions", idxs[:10])
# also player response
for pat in ["ytInitialPlayerResponse", "INNERTUBE_API_KEY", "INNERTUBE_CLIENT_NAME", "captionTracks", "playerCaptions"]:
    print(pat, [m.start() for m in re.finditer(pat, html)][:5])

# extract a json object after ytcfg.set
def extract_json_after(s, start):
    i=s.find("{", start)
    if i<0: return None
    depth=0
    in_str=False
    esc=False
    for j,ch in enumerate(s[i:], i):
        if in_str:
            if esc:
                esc=False
            elif ch=="\\":
                esc=True
            elif ch=='"':
                in_str=False
            continue
        else:
            if ch=='"':
                in_str=True
            elif ch=="{":
                depth+=1
            elif ch=="}":
                depth-=1
                if depth==0:
                    return s[i:j+1]
    return None

if idxs:
    blob=extract_json_after(html, idxs[0])
    print("blob len", len(blob) if blob else None)
    if blob:
        try:
            data=json.loads(blob)
            print("keys", list(data)[:40])
            for k in ["INNERTUBE_API_KEY","INNERTUBE_CLIENT_NAME","INNERTUBE_CLIENT_VERSION","INNERTUBE_CONTEXT_CLIENT_NAME","VISITOR_DATA"]:
                print(k, str(data.get(k))[:80] if data.get(k) else None)
        except Exception as e:
            print("json fail", e)
            print(blob[:400])

# search caption nearby
i=html.find("caption")
print("context caption", html[i-80:i+200])
